// File name (Phase 4, plan 4.7 D7): ERPNext decides it: <Template Name>_Spec Sheet.pdf, no brand
// prefix, spaces/brackets/dots kept (context.spec_sheet_file_name from get_spec_sheet_data).
const productInfo = $('Get Product Info').first().json;
const message = productInfo.message || {};
const erpData = Array.isArray(message.products) ? message.products[0] : {};
const context = message.context || {};

let fileName = context.spec_sheet_file_name;
if (!fileName) {
    // Older ERPNext without the file name: the previous naming.
    const webhookBody = $('Webhook').first().json.body || {};
    const brandDisplayName = webhookBody.brand === 'lighting_206' ? '206 Lighting' : 'ilLumenate Lighting';
    const productName = (erpData?.product_name || 'Product').replace(/[^a-zA-Z0-9 -\[\]]/g, '').trim();
    fileName = `${brandDisplayName}_${productName}_Spec Sheet.pdf`;
}

// The processed Base64 PDF returned by Vercel
const base64Data = $input.item.json.pdf_base64;
if (!base64Data) {
    throw new Error('Missing pdf_base64 in Vercel response.');
}

return {
  json: { success: true },
  binary: {
    data: {
      data: base64Data,
      mimeType: 'application/pdf',
      fileName: fileName
    }
  }
};

// 1. Safely extract the HTML string from 'Fetch Webflow Template'
const templateOutput = $('(ilL) Fetch Webflow Template').first().json;
let html = templateOutput.data || templateOutput.body || (typeof templateOutput === 'string' ? templateOutput : null);

if (!html) {
    throw new Error("HTML template string is missing from 'Fetch Webflow Template'.");
}

// 2. NUKE COOKIE CONSENT BANNERS & LAZY LOADING
html = html.replace(/<script[^>]*termly[^>]*><\/script>/gi, '');
html = html.replace(/<script[^>]*cookie[^>]*><\/script>/gi, '');
html = html.replace(/loading="lazy"/gi, ''); 

// 3. Extract fully enriched product
let erpData;
try {
    erpData = $('Get Product Info').first().json.message.products[0];
} catch (e) {
    erpData = $('Get Product Info').first().json.message.products[0];
}

// Pre-process Image URLs
if (erpData.featured_image && !erpData.featured_image.startsWith('http')) {
    erpData.featured_image = 'https://app.illumenate.lighting' + (erpData.featured_image.startsWith('/') ? '' : '/') + erpData.featured_image;
}
if (erpData.dimensions_image_dark && !erpData.dimensions_image_dark.startsWith('http')) {
    erpData.dimensions_image_dark = 'https://app.illumenate.lighting' + (erpData.dimensions_image_dark.startsWith('/') ? '' : '/') + erpData.dimensions_image_dark;
}

// 3b. Reconstruct template_doctype and template_name (Imported from 206 Script)
const templateMap = {
    tape_neon_template: 'ilL-Tape-Neon-Template',
    led_sheet_template: 'ilL-LED-Sheet-Template',
    kit_template: 'ilL-Extrusion-Kit-Template',
    fixture_template: 'ilL-Fixture-Template',
    driver_template: 'ilL-Driver-Template',
    controller_template: 'ilL-Controller-Template'
};

let resolved_template_doctype = null;
let resolved_template_name = null;

for (const [key, doctype] of Object.entries(templateMap)) {
    if (erpData[key]) {
        resolved_template_doctype = doctype;
        resolved_template_name = erpData[key];
        break;
    }
}

// 3c. Highlights for the configured spec sheet (plan 4.20, owner 2026-11-06). Per product
// category: which specification row shows which configurator step. A row's values are split on
// ", " and each value that is one of the step's option labels is tagged with "<step>:<code>";
// a "whole" row is tagged with every code of the step. The product page highlights the tags of
// the options the visitor picked. Categories without rules get no tags.
const HIGHLIGHT_RULES = {
    'Extrusion Kit': [
        { spec: 'Lenses', step_type: 'Lens Appearance' },
        { spec: 'Mounting', step_type: 'Mounting Method' },
        { spec: 'Finish', step_type: 'Finish' },
        { spec: 'Stock Length', step_type: 'Length', whole: true },
    ],
    // Linear fixtures (owner, 2026-11-24). Their Dry/Wet icons, Output Options and Delivered
    // Lumens tables and Accessories Dimensions titles are tagged in the page script (E2, E3b,
    // E4, E5) from fixture_tokens below.
    'Fixture Template': [
        { spec: 'Light Color (CCT)', step_type: 'CCT' },
        { spec: 'Lens Options', step_type: 'Lens Appearance' },
        { spec: 'Mounting Options', step_type: 'Mounting Method' },
        { spec: 'Finish Options', step_type: 'Finish' },
    ],
};
const parseValues = opt => {
    if (Array.isArray(opt.allowed_values)) return opt.allowed_values;
    try { const v = JSON.parse(opt.allowed_values_json || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; }
};
erpData.spec_highlights = {};
(HIGHLIGHT_RULES[erpData.product_type] || []).forEach(rule => {
    const step = (erpData.configurator_options || []).find(o => o.option_type === rule.step_type);
    if (!step) return;
    const values = parseValues(step).filter(v => v.code || v.value);
    const token = v => step.option_step + ':' + String(v.code || v.value).trim();
    erpData.spec_highlights[rule.spec] = rule.whole
        ? { whole: values.map(token).join(' ') }
        : { byLabel: Object.fromEntries(values.filter(v => v.label).map(v => [String(v.label).trim().toLowerCase(), token(v)])) };
});

// 3d. Fixture highlight tokens (owner, 2026-11-24): per step, its options' "<step>:<code>" tags
// by label (lower case) and by code. The Output step lists its outputs per lens ({lensMap}).
// A tag "<a>+<b>" needs both selections (the product page script, configured-spec-sheet.html).
const optionTokens = type => {
    const step = (erpData.configurator_options || []).find(o => o.option_type === type);
    const tokens = { byLabel: {}, byCode: {} };
    if (!step) return tokens;
    let raw = step.allowed_values;
    if (!raw) { try { raw = JSON.parse(step.allowed_values_json || '[]'); } catch (e) { raw = []; } }
    const list = Array.isArray(raw) ? raw : [].concat(...Object.values((raw && raw.lensMap) || {}));
    list.forEach(v => {
        const code = v && String(v.code || v.value || '').trim();
        if (!code) return;
        const token = step.option_step + ':' + code;
        tokens.byCode[code] = token;
        if (v.label) tokens.byLabel[String(v.label).trim().toLowerCase()] = token;
    });
    return tokens;
};
if (erpData.product_type === 'Fixture Template') {
    erpData.fixture_tokens = {
        rating: optionTokens('Environment Rating'),
        lens: optionTokens('Lens Appearance'),
        output: optionTokens('Output Level'),
        mounting: optionTokens('Mounting Method'),
    };
}

// 4. Inject global window.ERP_DATA object into head + Spacing CSS
const dataScript = `
<style>
    /* Force hide any hardcoded cookie banners just in case */
    [id*="termly"], [class*="termly"], #cookie-banner, .cookie-consent { display: none !important; }
    /* Force spacing between pages for clean PDF rendering */
    .page-wrapper { margin-bottom: 40px !important; page-break-after: always; }

  .w-webflow-badge { display: none !important; visibility: hidden !important; }
</style>
<script>
new MutationObserver(() => document.querySelectorAll('.w-webflow-badge').forEach(el => el.remove()))
    .observe(document.documentElement, {childList: true, subtree: true});
    window.ERP_DATA = ${JSON.stringify(erpData).replace(/</g, '\\u003c')};
<\/script>`;

// 5. Client-side mapping & pagination script
const mappingScript = `<script>
  (function populateSpecSheet() {
      const data = window.ERP_DATA;
      if (!data) return;

      function setText(id, value) {
          const el = document.getElementById(id);
          if (el && value != null && value !== '') el.innerText = value;
      }

      function setImg(id, url) {
          const el = document.getElementById(id);
          if (el && url) el.src = url;
      }

      // Fixture highlight tags (owner, 2026-11-24): see fixture_tokens in the Format node.
      const fx = data.fixture_tokens || null;
      const tag = (el, value) => { if (el && value) el.setAttribute('data-highlight', value); };
      // On text (table cells, titles) the tag goes on an inline-block span around the text, so
      // the PDF generator's box fits the text rather than the whole cell.
      const tagText = (el, value) => {
          if (!el || !value) return;
          const span = document.createElement('span');
          span.style.display = 'inline-block';
          span.textContent = el.textContent;
          el.textContent = '';
          el.appendChild(span);
          tag(span, value);
      };
      const both = (outputToken, lensTokens) => outputToken
          ? lensTokens.map(lens => outputToken + '+' + lens).join(' ') : '';

      // --- A. CORE HEADERS & INFO ---
      setText('product-name', data.product_name);
      setText('sublabel', data.sublabel);

      // --- B. IMAGES ---
      setImg('feat-img', data.featured_image);
      setImg('spec-dims-img', data.dimensions_image_dark);

      // --- B2. DIMENSIONS TITLE (LED Neon; owner, 2026-11-19) ---
      // The first .dimension-item's #dimension-title takes the template's Dimensions Title, or is
      // hidden without one. (#dimension-item is the pattern for the Spec Gallery drawings.)
      const firstDimension = document.querySelector('.dimension-item:not(#dimension-item)');
      const firstDimensionTitle = firstDimension ? firstDimension.querySelector('#dimension-title') : null;
      if (firstDimensionTitle) {
          firstDimensionTitle.removeAttribute('id');
          if (data.dimensions_title) firstDimensionTitle.innerText = data.dimensions_title;
          else firstDimensionTitle.style.display = 'none';
      }

      // --- C. DYNAMIC SPECIFICATIONS GRID ---
      const specSection = document.getElementById('specifications');
      if (specSection && Array.isArray(data.specifications)) {
          const masterSpecItem = specSection.querySelector('#spec-data-item');
          if (masterSpecItem) {
              masterSpecItem.style.display = 'none';

              // With an Output Options table (fixtures), its numbers are not repeated here.
              const inTable = ((data.output_options || {}).rows || []).length
                  ? ['Watts per Foot', 'Max Run Length', 'Max Footage per 100W Supply'] : [];
              const filteredSpecs = data.specifications
                  .filter(spec => spec.spec_label !== "Output Options" && spec.spec_label !== "Certifications & Ratings")
                  .filter(spec => !inTable.includes(spec.spec_label))
                  .sort((a, b) => (a.display_order || 0) - (b.display_order || 0));

              Array.from(specSection.children).forEach(child => {
                  if (child.id === 'spec-data-item' && child !== masterSpecItem) child.remove();
              });

              filteredSpecs.forEach(spec => {
                  if (spec.spec_value) {
                      const itemClone = masterSpecItem.cloneNode(true);
                      itemClone.style.display = '';
                      itemClone.removeAttribute('id');

                      const titleEl = itemClone.querySelector('#spec-data-title');
                      const valueEl = itemClone.querySelector('#spec-data-value');

                      if (titleEl) titleEl.innerText = spec.spec_label;
                      if (valueEl) {
                          let finalValue = spec.spec_value;
                          if (spec.spec_unit) finalValue += " " + spec.spec_unit;
                          valueEl.innerText = finalValue;
                          // Configured spec sheet highlights (plan 4.20): tag the values tied to
                          // configurator options; the PDF generator stores their positions.
                          const rule = (data.spec_highlights || {})[spec.spec_label];
                          const tagged = (text, tokens) => {
                              const span = document.createElement('span');
                              span.style.display = 'inline-block';
                              span.textContent = text;
                              if (tokens) span.setAttribute('data-highlight', tokens);
                              return span;
                          };
                          if (rule && rule.whole) {
                              valueEl.textContent = '';
                              valueEl.appendChild(tagged(finalValue, rule.whole));
                          } else if (rule && rule.byLabel) {
                              valueEl.textContent = '';
                              String(finalValue).split(', ').forEach((part, i) => {
                                  if (i) valueEl.appendChild(document.createTextNode(', '));
                                  valueEl.appendChild(tagged(part, rule.byLabel[part.trim().toLowerCase()]));
                              });
                          }
                      }

                      specSection.appendChild(itemClone);
                  }
              });

              const activeRows = specSection.querySelectorAll('.spec-data-item:not([style*="display: none"])');
              if (activeRows.length > 0) activeRows[activeRows.length - 1].classList.add('last-row');
          }
      }

      // --- D. PART NUMBER BUILDER ---
      const builderSection = document.getElementById('part-no-builder');
      if (builderSection && Array.isArray(data.configurator_options) && data.configurator_options.length > 0) {

          // 1. Setup Fixed Series Block
          const seriesSlug = (data.product_slug || "").toUpperCase();
          const seriesCodes = builderSection.querySelectorAll('#series-code');
          seriesCodes.forEach(el => el.innerText = seriesSlug);
          setText('series-desc', "ilLumenate " + (data.product_name || ""));

          // Radio button colour for the PDF generator (owner, 2026-11-18): linear fixtures
          // #ffac33, LED Neon, LED Tape, COB Tape and LED Sheet #ff990a (owner, 2026-11-19); other
          // products keep the generator's green.
          const radioColor = {
              'Fixture Template': '#ffac33',
              'LED Neon': '#ff990a', 'LED Tape': '#ff990a', 'COB Tape': '#ff990a', 'LED Sheet': '#ff990a',
          }[data.product_type];
          if (radioColor) builderSection.setAttribute('data-radio-color', radioColor);

          // TAG THE SERIES BUTTON FOR VERCEL. Step 0 unless a configurator step already uses 0
          // (LED Neon's IP Rating; owner, 2026-11-19): then 'S', so the PDF fields do not clash.
          const seriesStep = data.configurator_options.some(opt => String(opt.option_step) === '0' && opt.option_type !== 'Series') ? 'S' : '0';
          const seriesBtn = builderSection.querySelector('#series-btn');
          if (seriesBtn) {
              seriesBtn.setAttribute('data-step', seriesStep);
              seriesBtn.setAttribute('data-code', seriesSlug);
          }

          // 2. Setup Dynamic Option Blocks
          // Fixtures (owner, 2026-11-13): the Length step gets the .part-no-length block, a free text
          // box tagged data-input-step for the PDF generator; each Feed Direction step gets a
          // .part-no-feed-section (the "feed-direction-title" one for directions, the
          // "feed-length-title" one for lengths), with no dash between a feed direction and its
          // length. Steps 90 and up are lookup tables (Finish to Endcap Color, Fixture Output
          // Level), not part number steps. #part-no-ex is the series and each step's first option,
          // with 50 for the Length.
          const wrapper = builderSection.querySelector('.part-no-wrapper');
          if (wrapper) {
              const dashTemplate = wrapper.querySelector('.part-no-dash');
              const sectionTemplate = wrapper.querySelector('.part-no-section');
              const lengthTemplate = wrapper.querySelector('.part-no-length');
              const feedTemplates = Array.from(wrapper.querySelectorAll('.part-no-feed-section'));
              const feedDirTemplate = feedTemplates.find(el => el.querySelector('#feed-direction-title')) || feedTemplates[0];
              const feedLenTemplate = feedTemplates.find(el => el.querySelector('#feed-length-title')) || feedTemplates[1] || feedDirTemplate;

              if (dashTemplate && sectionTemplate) {
                  dashTemplate.style.display = 'none';
                  sectionTemplate.style.display = 'none';
                  [lengthTemplate, ...feedTemplates].forEach(el => { if (el) el.remove(); });

                  // Clear placeholder dynamic sections
                  Array.from(wrapper.children).forEach(child => {
                      if (!child.classList.contains('part-1-wrapper') && child !== dashTemplate && child !== sectionTemplate) {
                          child.remove();
                      }
                  });

                  const addDash = () => {
                      const dashClone = dashTemplate.cloneNode(true);
                      dashClone.style.display = '';
                      // The page's .part-no-dash has height: 100%, which made each row as tall as
                      // the whole builder (the big gap under the first row; owner, 2026-11-18).
                      dashClone.style.height = 'auto';
                      wrapper.appendChild(dashClone);
                  };

                  const fillOptions = (sectionClone, opt, values) => {
                      const optionsWrapper = sectionClone.querySelector('.part-no-options-wrapper');
                      const optTemplate = sectionClone.querySelector('#part-no-options');
                      if (!optionsWrapper || !optTemplate) return;
                      optTemplate.style.display = 'none';
                      Array.from(optionsWrapper.children).forEach(child => {
                          if (child !== optTemplate) child.remove();
                      });
                      values.forEach(valObj => {
                          const optClone = optTemplate.cloneNode(true);
                          optClone.style.display = '';
                          optClone.removeAttribute('id');

                          // TAG THE DYNAMIC BUTTONS FOR VERCEL
                          optClone.setAttribute('data-step', opt.option_step);
                          optClone.setAttribute('data-code', valObj.code || valObj.value);

                          const codeEl = optClone.querySelector('#part-no-code');
                          const descEl = optClone.querySelector('#part-no-desc');
                          if (codeEl) codeEl.innerText = valObj.code || '';
                          // A blank code (a feed length's "Endcap") reads "blank" in italics, so
                          // customers know it is left empty (owner, 2026-11-19).
                          if (codeEl && valObj.code === '') {
                              codeEl.innerText = 'blank';
                              codeEl.style.fontStyle = 'italic';
                          }
                          if (descEl) descEl.innerText = valObj.label || valObj.value || '';
                          optionsWrapper.appendChild(optClone);
                      });
                  };

                  const example = [seriesSlug];
                  let lastWasFeedDir = false;
                  // A feed direction and its feed length share one box, so they always wrap to a
                  // new row together (LED Neon preview; owner, 2026-11-19).
                  let feedPair = null;
                  const sortedConfig = data.configurator_options
                      .filter(opt => Number(opt.option_step) < 90)
                      .sort((a, b) => a.option_step - b.option_step);

                  sortedConfig.forEach(opt => {
                      let currentValues = [];
                      try {
                          currentValues = JSON.parse(opt.allowed_values_json || "[]");
                      } catch(e) {}
                      // A fixture's Output step lists its outputs per lens ({lensMap: {WH: [...]}}):
                      // the builder shows each output once, lowest first.
                      if (!Array.isArray(currentValues)) {
                          const byCode = new Map();
                          Object.values((currentValues && currentValues.lensMap) || {}).forEach(list => {
                              (Array.isArray(list) ? list : []).forEach(v => {
                                  if (v && v.code && !byCode.has(String(v.code))) byCode.set(String(v.code), { code: String(v.code), label: v.label || String(v.code) });
                              });
                          });
                          currentValues = Array.from(byCode.values()).sort((a, b) => (parseFloat(a.code) || 0) - (parseFloat(b.code) || 0));
                      }
                      // The Output step lists exactly the Output Options table's outputs (owner,
                      // 2026-11-19): no per-square-foot levels (the stray 550) and nothing the table lacks.
                      const tableOutputs = ((data.output_options || {}).columns || []).filter(Boolean);
                      if (opt.option_type === 'Output Level' && tableOutputs.length) {
                          currentValues = tableOutputs.map(code => ({ code: String(code), label: code + ' lm/ft' }));
                      }
                      const label = opt.option_label || opt.option_type || '';

                      // A free length (fixtures) has only the length metadata row; a kit's stock
                      // length is an ordinary step.
                      const freeLength = opt.option_type === 'Length' && currentValues.length > 0
                          && currentValues.every(v => v && v.value === '__length_metadata__');
                      if (freeLength) {
                          lastWasFeedDir = false;
                          if (!lengthTemplate) return;
                          addDash();
                          const lengthClone = lengthTemplate.cloneNode(true);
                          lengthClone.style.display = '';
                          lengthClone.setAttribute('data-input-step', opt.option_step);
                          const lengthInput = lengthClone.querySelector('#part-no-length-input');
                          if (lengthInput) lengthInput.innerHTML = '';
                          wrapper.appendChild(lengthClone);
                          example.push('50');
                          return;
                      }

                      const values = currentValues.filter(v => v && (v.code || v.label || v.value));
                      if (values.length === 0) return;
                      // A blank code (a feed length's "Endcap"; owner, 2026-11-19) adds nothing.
                      const firstCode = values[0].code === '' ? '' : String(values[0].code || values[0].value || '');

                      // LED Neon stores the directions as Start/End Feed Direction (owner, 2026-11-19).
                      const isFeed = ['Feed Direction', 'Start Feed Direction', 'End Feed Direction'].includes(opt.option_type) && feedDirTemplate;
                      const isFeedLength = isFeed && /length/i.test(label);
                      let sectionClone;
                      if (isFeed) {
                          // A feed length sits right after its feed direction, with no dash.
                          if (!(isFeedLength && lastWasFeedDir)) addDash();
                          sectionClone = (isFeedLength ? feedLenTemplate : feedDirTemplate).cloneNode(true);
                          const titleEl = sectionClone.querySelector('#feed-direction-title, #feed-length-title, .part-no-title');
                          if (titleEl) titleEl.innerText = label.toUpperCase();
                          const inputEl = sectionClone.querySelector('.part-no-feeddir-input');
                          if (inputEl) inputEl.innerHTML = '';
                          if (isFeedLength && lastWasFeedDir) example[example.length - 1] += firstCode;
                          else example.push(firstCode);
                          lastWasFeedDir = !isFeedLength;
                      } else {
                          addDash();
                          sectionClone = sectionTemplate.cloneNode(true);
                          const titleEl = sectionClone.querySelector('#part-no-title');
                          if (titleEl) titleEl.innerText = label.toUpperCase();
                          const inputEl = sectionClone.querySelector('#part-no-code-input');
                          if (inputEl) inputEl.innerHTML = ''; // Empty out placeholder
                          example.push(firstCode);
                          lastWasFeedDir = false;
                      }
                      sectionClone.style.display = '';
                      fillOptions(sectionClone, opt, values);
                      if (isFeed && !isFeedLength) {
                          feedPair = document.createElement('div');
                          feedPair.className = 'ill-feed-pair';
                          feedPair.style.display = 'flex';
                          feedPair.style.flex = '0 0 auto';
                          wrapper.appendChild(feedPair);
                          feedPair.appendChild(sectionClone);
                      } else if (isFeedLength && feedPair) {
                          feedPair.appendChild(sectionClone);
                          feedPair = null;
                      } else {
                          feedPair = null;
                          wrapper.appendChild(sectionClone);
                      }
                  });

                  const exampleEl = document.getElementById('part-no-ex');
                  if (exampleEl) exampleEl.innerText = example.filter(Boolean).join('-');
                  // Rows stay 20px apart (the wrapper's row gap): a wrapper taller than its rows
                  // would otherwise stretch them apart (owner, 2026-11-18).
                  wrapper.style.alignContent = 'flex-start';
                  wrapper.style.height = 'auto';
              }
          }
      } else if (builderSection) {
          builderSection.style.display = 'none';
      }

      // --- E. EXTRUSION KIT COMPONENTS ---
      const compSection = document.getElementById('components');
      if (compSection && Array.isArray(data.kit_components) && data.kit_components.length > 0) {

          let listWrapper = compSection.querySelector('.component-list-wrapper') || compSection.querySelector('.div-12') || compSection;
          const masterGroup = compSection.querySelector('#component-wrapper');

          if (masterGroup) {
              masterGroup.style.display = 'none';

              Array.from(listWrapper.children).forEach(child => {
                  if (child.id === 'component-wrapper' && child !== masterGroup) child.remove();
              });

              data.kit_components.forEach(group => {
                  let parsedRows = [];
                  try {
                      parsedRows = JSON.parse(group.component_description || "[]");
                  } catch(e) {}

                  if (parsedRows.length > 0) {
                      const groupClone = masterGroup.cloneNode(true);
                      groupClone.style.display = '';
                      groupClone.removeAttribute('id');

                      const titleEl = groupClone.querySelector('#component-title');
                      if (titleEl) titleEl.innerText = group.component_type;

                      let heroUrl = null;
                      if (parsedRows[0] && parsedRows[0].hero_image) {
                          heroUrl = parsedRows.shift().hero_image;
                      }

                      const imgEl = groupClone.querySelector('#component-img');
                      if (imgEl && heroUrl) {
                          imgEl.src = heroUrl;
                      } else if (imgEl) {
                          imgEl.style.display = 'none';
                      }

                      // Deduplicate and reformat Endcap Sets
                      if (group.component_type === 'Endcap Set' || group.component_type === 'Endcaps') {
                          const uniqueEndcaps = new Map();
                          parsedRows.forEach(row => {
                              if (row.code || row.label) {
                                  const cleanCode = (row.code || '').replace(/-NO$/i, '').replace(/-HO$/i, '');
                                  if (!uniqueEndcaps.has(cleanCode)) {
                                      uniqueEndcaps.set(cleanCode, { code: cleanCode, label: row.label });
                                  }
                              }
                          });
                          parsedRows = Array.from(uniqueEndcaps.values());
                      }

                      const rowsContainer = groupClone.querySelector('#comp-partno-wrap');
                      if (rowsContainer) {
                          const masterRow = rowsContainer.querySelector('#component-option');
                          if (masterRow) {
                              masterRow.style.display = 'none';

                              Array.from(rowsContainer.children).forEach(child => {
                                  if (child !== masterRow) child.remove();
                              });

                              parsedRows.forEach(row => {
                                  if(row.code || row.label) {
                                      const rowClone = masterRow.cloneNode(true);
                                      rowClone.style.display = '';
                                      rowClone.removeAttribute('id');

                                      const codeEl = rowClone.querySelector('#comp-code');
                                      const descEl = rowClone.querySelector('#comp-desc');

                                      if (codeEl) codeEl.innerText = row.code;
                                      if (descEl) descEl.innerText = row.label;

                                      rowsContainer.appendChild(rowClone);
                                  }
                              });

                              const activeOptions = rowsContainer.querySelectorAll('.component-option:not([style*="display: none"])');
                              if (activeOptions.length > 0) activeOptions[activeOptions.length - 1].classList.add('last-row');
                          }
                      }

                      listWrapper.appendChild(groupClone);
                  }
              });
          }
      } else if (compSection) {
          compSection.style.display = 'none';
      }

      // --- E2. CERTIFICATION BADGES (one .cert-icon per template certification) ---
      // The first .cert-icon is the pattern: it is copied once per certification that has a
      // badge (the template's Badge Image), then hidden. No badges: it stays hidden.
      const certTemplate = document.querySelector('.cert-icon');
      if (certTemplate) {
          const badges = (Array.isArray(data.certifications) ? data.certifications : [])
              .filter(c => c.certification_details && c.certification_details.badge_image);
          document.querySelectorAll('.cert-icon').forEach(el => { if (el !== certTemplate) el.remove(); });
          let anchor = certTemplate;
          badges.forEach(cert => {
              const url = cert.certification_details.badge_image;
              const icon = certTemplate.cloneNode(true);
              icon.style.display = '';
              icon.removeAttribute('id');
              const img = icon.tagName === 'IMG' ? icon : icon.querySelector('img');
              if (img) { img.src = url; img.removeAttribute('srcset'); img.removeAttribute('loading'); }
              // Dry/Wet (fixtures): "Dry Rated" is the Dry option, and so on.
              if (fx) tag(icon, fx.rating.byLabel[String(cert.certification || '').trim().toLowerCase().replace(/\\s*rated$/, '')]);
              anchor.parentNode.insertBefore(icon, anchor.nextSibling);
              anchor = icon;
          });
          certTemplate.style.display = 'none';
      }

      // --- E3. EXTRA DIMENSION IMAGES (Spec Gallery, section "Dimensions") ---
      // The first .dimension-item keeps dimensions_image (#spec-dims-img). #dimension-item is the
      // pattern for the extra ones: copied once per Dimensions row (title in #dimension-title,
      // hidden when empty; image in #spec-dims-img-other), then hidden. No rows: stays hidden.
      const dimTemplate = document.getElementById('dimension-item');
      if (dimTemplate) {
          const rows = (Array.isArray(data.spec_gallery) ? data.spec_gallery : [])
              .filter(row => row.section === 'Dimensions' && row.image);
          let anchor = dimTemplate;
          rows.forEach(row => {
              const item = dimTemplate.cloneNode(true);
              item.style.display = '';
              item.removeAttribute('id');
              const titleEl = item.querySelector('#dimension-title');
              if (titleEl) {
                  titleEl.removeAttribute('id');
                  if (row.title) { titleEl.innerText = row.title; } else { titleEl.style.display = 'none'; }
              }
              const imgEl = item.querySelector('#spec-dims-img-other');
              if (imgEl) {
                  imgEl.removeAttribute('id');
                  imgEl.src = row.image;
                  imgEl.removeAttribute('srcset');
                  imgEl.removeAttribute('loading');
              }
              anchor.parentNode.insertBefore(item, anchor.nextSibling);
              anchor = item;
          });
          dimTemplate.style.display = 'none';
      }

      // --- E3b. ACCESSORIES DIMENSIONS (Spec Gallery, section "Accessories Dimensions") ---
      // #accdimension-item is the pattern: copied once per row (title in #accdimension-title,
      // hidden when empty; image in #accdim-img), then removed. No rows: the section is hidden.
      const accSection = document.getElementById('acc-dimensions');
      if (accSection) {
          const accTemplate = accSection.querySelector('#accdimension-item');
          const accRows = (Array.isArray(data.spec_gallery) ? data.spec_gallery : [])
              .filter(row => row.section === 'Accessories Dimensions' && row.image);
          if (!accTemplate || accRows.length === 0) {
              accSection.style.display = 'none';
          } else {
              let anchor = accTemplate;
              accRows.forEach(row => {
                  const item = accTemplate.cloneNode(true);
                  item.removeAttribute('id');
                  const titleEl = item.querySelector('#accdimension-title');
                  if (titleEl) {
                      titleEl.removeAttribute('id');
                      if (row.title) { titleEl.innerText = row.title; } else { titleEl.style.display = 'none'; }
                      // Mounting (fixtures): the title names the mounting option.
                      if (fx && row.title) tagText(titleEl, fx.mounting.byLabel[String(row.title).trim().toLowerCase()]);
                  }
                  const imgEl = item.querySelector('#accdim-img');
                  if (imgEl) {
                      imgEl.removeAttribute('id');
                      imgEl.src = row.image;
                      imgEl.removeAttribute('srcset');
                      imgEl.removeAttribute('loading');
                  }
                  anchor.parentNode.insertBefore(item, anchor.nextSibling);
                  anchor = item;
              });
              accTemplate.remove();
          }
      }

      // --- E3c. COMPATIBLE POWER SUPPLIES (the template's table, by max wattage) ---
      // The columns follow the page's .table-title headers (matched by their text); the first
      // .table-item-wrapper is the row pattern, its .table-item cells in the same order. The
      // last row gets last-row. No rows: the section is hidden.
      const supplySection = document.getElementById('power-supplies');
      if (supplySection) {
          const supplies = Array.isArray(data.custom_compatible_power_supplies) ? data.custom_compatible_power_supplies : [];
          const body = supplySection.querySelector('.table-data-wrapper');
          const pattern = body ? body.querySelector('.table-item-wrapper') : null;
          if (!supplies.length || !body || !pattern) {
              supplySection.style.display = 'none';
          } else {
              const SUPPLY_COLUMNS = {
                  'part number': 'part_number',
                  'input protocol': 'input_protocol',
                  'voltage/frequency': 'voltagefrequency',
                  'output voltage': 'output_voltage',
                  'max wattage': 'max_wattage',
                  'output count': 'output_count',
                  'location rating': 'location_rating',
              };
              const columns = Array.from(supplySection.querySelectorAll('.table-title-wrapper .table-title'))
                  .map(el => SUPPLY_COLUMNS[el.innerText.trim().toLowerCase()] || null);
              Array.from(body.children).forEach(child => child.remove());
              supplies.forEach((supply, r) => {
                  const line = pattern.cloneNode(true);
                  line.classList.toggle('last-row', r === supplies.length - 1);
                  line.querySelectorAll('.table-item').forEach((cell, i) => {
                      const key = columns[i];
                      cell.innerText = key && supply[key] != null ? String(supply[key]) : '';
                  });
                  body.appendChild(line);
              });
          }
      }

      // --- E3d. EMISSION ANGLE and BEND DIAMETER (LED Neon; owner, 2026-11-19) ---
      // From the Spec Gallery rows of those Sections: the item (#emission-item / #benddia-item)
      // is copied once per row, its title (hidden when empty) and image filled, then removed.
      // No rows: the section is hidden.
      const gallerySection = (sectionId, itemId, titleId, imgId, gallerySectionName) => {
          const section = document.getElementById(sectionId);
          if (!section) return;
          const pattern = section.querySelector('#' + itemId);
          const rows = (Array.isArray(data.spec_gallery) ? data.spec_gallery : [])
              .filter(row => row.section === gallerySectionName && row.image);
          if (!pattern || rows.length === 0) { section.style.display = 'none'; return; }
          let anchor = pattern;
          rows.forEach(row => {
              const item = pattern.cloneNode(true);
              item.removeAttribute('id');
              const titleEl = item.querySelector('#' + titleId);
              if (titleEl) {
                  titleEl.removeAttribute('id');
                  if (row.title) { titleEl.innerText = row.title; } else { titleEl.style.display = 'none'; }
              }
              const imgEl = item.querySelector('#' + imgId);
              if (imgEl) {
                  imgEl.removeAttribute('id');
                  imgEl.src = row.image;
                  imgEl.removeAttribute('srcset');
                  imgEl.removeAttribute('loading');
              }
              anchor.parentNode.insertBefore(item, anchor.nextSibling);
              anchor = item;
          });
          pattern.remove();
      };
      gallerySection('emission-angle', 'emission-item', 'emission-title', 'emission-img', 'Emission Angle');
      gallerySection('bend-diameter', 'benddia-item', 'benddia-title', 'benddia-img', 'Bend Diameter(s)');

      // --- E3e. MOUNTING ACCESSORIES (LED Neon; owner, 2026-11-19) ---
      // #mounting-acc: the first .component-option is the row pattern, copied once per accessory
      // (#acc-code: the item code; #acc-desc: its Item Name); the last row gets last-row.
      // No accessories: the block is hidden.
      const mountSection = document.getElementById('mounting-acc');
      if (mountSection) {
          const accessories = Array.isArray(data.mounting_accessories) ? data.mounting_accessories : [];
          const wrap = mountSection.querySelector('.comp-partno-wrap');
          const pattern = wrap ? wrap.querySelector('.component-option') : null;
          if (!accessories.length || !pattern) {
              mountSection.style.display = 'none';
          } else {
              Array.from(wrap.children).forEach(child => child.remove());
              accessories.forEach((accessory, i) => {
                  const line = pattern.cloneNode(true);
                  line.removeAttribute('id');
                  line.classList.toggle('last-row', i === accessories.length - 1);
                  const codeEl = line.querySelector('#acc-code');
                  const descEl = line.querySelector('#acc-desc');
                  if (codeEl) { codeEl.innerText = accessory.code || ''; codeEl.removeAttribute('id'); }
                  if (descEl) { descEl.innerText = accessory.label || ''; descEl.removeAttribute('id'); }
                  wrap.appendChild(line);
              });
          }
      }

      // Accessories Dimensions on LED Neon: #acc-label under each image has no data yet; hidden.
      document.querySelectorAll('[id="acc-label"]').forEach(el => { el.style.display = 'none'; });

      // --- GRADIENT LINES (owner, 2026-11-13) ---
      // The page has one header and one footer gradient line per family (#fs-, #sw-, #tw-,
      // #dw-gradient-line and #fsfooter-... to #dwfooter-gradient-line). The template's LED
      // packages pick the ones shown; the others are hidden. No known package: nothing changes.
      const GRADIENTS = {
          'ilLumenate Static White': 'sw',
          'ilLumenate Tunable White': 'tw',
          // RGBW has its own cc line where the page has one (LED Neon; owner, 2026-11-19).
          'ilLumenate RGBW': document.querySelector('[id="cc-gradient-line"]') ? 'cc' : 'fs',
          'ilLumenate RGB+TW': 'fs',
          'ilLumenate Color Changing Pixel': 'fs',
          'ilLumenate Dim to Warm': 'dw',
      };
      const shownGradients = new Set((data.led_packages || []).map(p => GRADIENTS[p]).filter(Boolean));
      if (shownGradients.size > 0) {
          ['fs', 'sw', 'tw', 'dw', 'cc'].forEach(key => {
              // Ids may repeat (the neon page's footer cc line shares its id with the header one).
              document.querySelectorAll('[id="' + key + '-gradient-line"], [id="' + key + 'footer-gradient-line"]').forEach(line => {
                  line.style.display = shownGradients.has(key) ? '' : 'none';
              });
          });
      }

      // --- E5. OUTPUT OPTIONS (fixtures; owner, 2026-11-18) ---
      // #output-options: in .table-title-wrapper the first .table-title keeps its text and #output
      // (or the second .table-title) is the pattern for the output columns; in
      // .table-data-wrapper the first .table-item-wrapper is the row pattern: its first child
      // (the .spec-h3) takes the row label ("Fixture Wattage (White Lens)") and #output-data (or
      // the second child) is the pattern for the values. The last row gets last-row. No rows:
      // the section is hidden.
      const optionSection = document.getElementById('output-options');
      if (optionSection) {
          const options = data.output_options || {};
          const columns = options.columns || [];
          const optionRows = options.rows || [];
          const head = optionSection.querySelector('.table-title-wrapper');
          const body = optionSection.querySelector('.table-data-wrapper');
          const rowPattern = body ? body.querySelector('.table-item-wrapper') : null;
          const titles = head ? Array.from(head.querySelectorAll('.table-title')) : [];
          if (!columns.length || !optionRows.length || !rowPattern || titles.length < 2) {
              optionSection.style.display = 'none';
          } else {
              const titlePattern = head.querySelector('#output') || titles[1];
              titles.slice(1).forEach(el => el.remove());
              columns.forEach(column => {
                  const cell = titlePattern.cloneNode(true);
                  cell.removeAttribute('id');
                  cell.innerText = column;
                  if (fx) tagText(cell, fx.output.byCode[String(column)]);
                  head.appendChild(cell);
              });
              // Fixtures: a value cell needs its column's output and its row's lens ("(White
              // Lens)"); "(Other Lenses)" is every lens no other row names.
              const lensOf = label => { const m = /\\(([^)]+?)\\s+lens(es)?\\)/i.exec(label || ''); return m ? m[1].trim().toLowerCase() : null; };
              const namedLenses = new Set(optionRows.map(row => lensOf(row.label)).filter(name => name && name !== 'other'));
              const rowLensTokens = label => {
                  if (!fx) return [];
                  const name = lensOf(label);
                  if (name === 'other') return Object.entries(fx.lens.byLabel).filter(([key]) => !namedLenses.has(key)).map(([, token]) => token);
                  return name && fx.lens.byLabel[name] ? [fx.lens.byLabel[name]] : [];
              };
              const items = Array.from(rowPattern.children);
              const cellPattern = rowPattern.querySelector('#output-data') || items[1] || items[0];
              Array.from(body.children).forEach(child => child.remove());
              optionRows.forEach((row, r) => {
                  const line = rowPattern.cloneNode(false);
                  line.classList.toggle('last-row', r === optionRows.length - 1);
                  const label = items[0].cloneNode(true);
                  label.removeAttribute('id');
                  label.innerText = row.label || '';
                  line.appendChild(label);
                  const lensTokens = rowLensTokens(row.label);
                  (row.values || []).forEach((value, c) => {
                      const cell = cellPattern.cloneNode(true);
                      cell.removeAttribute('id');
                      cell.innerText = value;
                      if (fx) tagText(cell, both(fx.output.byCode[String(columns[c])], lensTokens));
                      line.appendChild(cell);
                  });
                  body.appendChild(line);
              });
          }
      }

      // --- E4. DELIVERED LUMENS (fixtures; owner, 2026-11-13) ---
      // Header: the first .table-title is "Output"; the next ones (#lumen-table-lens) take the
      // template's lenses in order. Rows: the first .table-item-wrapper is the pattern, copied once
      // per output (#output-item, then #output-c1..c4 for the lenses). Cells for lenses the
      // template does not have are removed. No rows: the section is hidden.
      const lumenSection = document.getElementById('delivered-lumens');
      if (lumenSection) {
          const lumens = data.delivered_lumens || {};
          const lenses = lumens.lenses || [];
          const lumenRows = lumens.rows || [];
          if (!lenses.length || !lumenRows.length) {
              lumenSection.style.display = 'none';
          } else {
              const head = lumenSection.querySelector('.table-title-wrapper');
              const lensCells = head ? Array.from(head.querySelectorAll('.table-title')).slice(1) : [];
              // Fixtures: the lens headers take the Lens step, the output labels the Output step,
              // and each value both.
              const lensToken = i => (fx && lenses[i] ? fx.lens.byLabel[String(lenses[i].label).trim().toLowerCase()] : '');
              lensCells.forEach((cell, i) => {
                  if (i < lenses.length) { cell.innerText = lenses[i].label; cell.removeAttribute('id'); tagText(cell, lensToken(i)); }
                  else cell.remove();
              });
              const body = lumenSection.querySelector('.table-data-wrapper');
              const pattern = body ? body.querySelector('.table-item-wrapper') : null;
              if (body && pattern) {
                  Array.from(body.children).forEach(child => child.remove());
                  lumenRows.forEach((row, r) => {
                      const line = pattern.cloneNode(true);
                      line.classList.toggle('last-row', r === lumenRows.length - 1);
                      const label = line.querySelector('#output-item');
                      const outputToken = fx ? fx.output.byCode[String(parseFloat(row.output))] : '';
                      if (label) { label.innerText = row.output || ''; label.removeAttribute('id'); tagText(label, outputToken); }
                      for (let i = 1; i <= 4; i++) {
                          const cell = line.querySelector('#output-c' + i);
                          if (!cell) continue;
                          if (i <= lenses.length) {
                              cell.innerText = (row.values || {})[lenses[i - 1].key] || '—';
                              cell.removeAttribute('id');
                              if (fx && lensToken(i - 1)) tagText(cell, both(outputToken, [lensToken(i - 1)]));
                          } else {
                              cell.remove();
                          }
                      }
                      body.appendChild(line);
                  });
              }
          }
      }

      // --- F. GENERATED DATE (Strictly MMDDYY) ---
      const now = new Date();
      const mm = String(now.getMonth() + 1).padStart(2, '0');
      const dd = String(now.getDate()).padStart(2, '0');
      const yy = String(now.getFullYear()).slice(-2);

      // <TAG>.<MMDDYY> from ERPNext (tag of the stored file, Pacific date); the date alone if missing.
      setText('generated-date', data.spec_sheet_stamp || (mm + dd + yy));

      // --- G. PAGINATION LOGIC (1056px Max Height) ---
      // Measured once the page and its web fonts have loaded: measured in the fallback font, text
      // wrapped less than in the PDF and a section could run into the footer (owner, 2026-11-18).
      // SAFETY keeps a little room for what still differs when the PDF is drawn.
      const paginate = () => {
      const PAGE_HEIGHT = 1056; 
      const SAFETY = 12;
      const container = document.querySelector('.pdf-spec-container');
      let currentPage = document.querySelector('.page-wrapper');

      if (container && currentPage) {
          // Measured by its content: with its 1056px minimum height a page always measured full
          // once the safety margin was taken off (owner, 2026-11-18). Pages get 1056px at the end.
          currentPage.style.height = 'auto';
          currentPage.style.minHeight = '0px';

          let currentMain = currentPage.querySelector('.spec-main-wrapper');
          const sections = Array.from(currentMain.children);

          currentMain.innerHTML = '';

          function addPage() {
              const newPage = currentPage.cloneNode(true);
              const newMain = newPage.querySelector('.spec-main-wrapper');
              newMain.innerHTML = ''; 
              container.appendChild(newPage);
              currentPage = newPage;
              currentMain = newMain;
          }

          // Page rules (owner, 2026-11-18):
          // - the Part Number Builder always starts its own page, title and example included;
          // - a kit's Components start their own page (fixtures' flow on);
          // - a section split over two pages keeps its title (.spec-h2, and the builder's
          //   example line) with the content that follows it.
          const visible = el => el.style.display !== 'none';
          const pageHasContent = () => Array.from(currentMain.children).some(visible);
          const isHeading = el => el.classList.contains('spec-h2') || !!el.querySelector('#part-no-ex') || el.id === 'part-no-ex';
          sections.forEach(section => {
              const ownPage = visible(section) && (section.id === 'part-no-builder'
                  || (section.id === 'components' && data.product_type === 'Extrusion Kit'));
              if (ownPage && pageHasContent()) addPage();

              currentMain.appendChild(section);
              if (currentPage.scrollHeight <= PAGE_HEIGHT - SAFETY) return;

              currentMain.removeChild(section);
              let activeSection = section.cloneNode(false);
              currentMain.appendChild(activeSection);
              Array.from(section.children).forEach(item => {
                  activeSection.appendChild(item);
                  if (currentPage.scrollHeight <= PAGE_HEIGHT - SAFETY) return;
                  // Carry the titles just before this item along with it.
                  const moving = [item];
                  while (moving[0].previousElementSibling && isHeading(moving[0].previousElementSibling)) {
                      moving.unshift(moving[0].previousElementSibling);
                  }
                  const emptied = moving.length === activeSection.children.length;
                  // Nothing else on this page: moving would not help, so it stays.
                  if (emptied && Array.from(currentMain.children).filter(visible).length === 1) return;
                  moving.forEach(el => activeSection.removeChild(el));
                  if (emptied) currentMain.removeChild(activeSection);
                  addPage();
                  activeSection = section.cloneNode(false);
                  currentMain.appendChild(activeSection);
                  moving.forEach(el => activeSection.appendChild(el));
              });
          });

          const allPages = document.querySelectorAll('.page-wrapper');
          allPages.forEach((page, idx) => {
              page.style.height = PAGE_HEIGHT + 'px';
              page.style.minHeight = PAGE_HEIGHT + 'px';
              page.style.overflow = 'hidden';

              const curEl = page.querySelector('#current-page-no');
              const totEl = page.querySelector('#total-page-no');
              if (curEl) curEl.innerText = (idx + 1).toString();
              if (totEl) totEl.innerText = allPages.length.toString();
          });
      }
      };
      const fontsReady = () => (document.fonts && document.fonts.ready ? document.fonts.ready : Promise.resolve());
      if (document.readyState === 'complete') fontsReady().then(paginate);
      else window.addEventListener('load', () => fontsReady().then(paginate));

  })();
<\/script>`;

// 6. Build final HTML string
// The footer separator ✦ (U+2726) is in no font the PDF renderer has, so it printed as empty boxes
// (owner, 2026-11-24). Draw it as a small inline SVG in the text colour instead. Only the page
// template is changed, before ERP_DATA is added.
const STAR_SVG = '<svg class="ill-star" viewBox="0 0 10 10" width="0.62em" height="0.62em" aria-hidden="true"'
    + ' style="display:inline-block;vertical-align:0.02em;fill:currentColor">'
    + '<path d="M5 0C5.6 3.4 6.6 4.4 10 5C6.6 5.6 5.6 6.6 5 10C4.4 6.6 3.4 5.6 0 5C3.4 4.4 4.4 3.4 5 0Z"/></svg>';
html = html.split('✦').join(STAR_SVG).split('&#10022;').join(STAR_SVG).split('&#x2726;').join(STAR_SVG);
let finalHtml = html;
const headCloseIndex = finalHtml.indexOf('</head>');
if (headCloseIndex !== -1) {
    finalHtml = finalHtml.substring(0, headCloseIndex) + dataScript + finalHtml.substring(headCloseIndex);
}

const bodyCloseIndex = finalHtml.lastIndexOf('</body>');
if (bodyCloseIndex !== -1) {
    finalHtml = finalHtml.substring(0, bodyCloseIndex) + mappingScript + finalHtml.substring(bodyCloseIndex);
}

// 7. Output matching data structure!
return {
    json: {
        injected_html: finalHtml,
        product_slug: erpData.product_slug,
        // The generator reads allowed_values (parsed) for the default selections.
        configurator_options: (erpData.configurator_options || []).map(opt => ({ ...opt, allowed_values: parseValues(opt) })),
        template_doctype: resolved_template_doctype,
        template_name: resolved_template_name
    }
};

// Code for the "(ilL) Transform to Webflow Format" node in the staging sync workflow (W2).
// Field mapping signed off by the owner on 2026-11-04/05: docs/erpnext_spec_sheet_redesign_plan.md
// sections 4.16 and 4.19. The template's fields come from payload.template (ERPNext
// webflow_sync_payload.template_section); the product's from payload.product (the export).
// Fields not listed here are never sent, so Webflow keeps whatever they hold.
const data = $('Set Brand Config').first().json;
const payload = data.payload || {};
const product = data.enriched_product || {};
const tpl = payload.template || null;
const brand = data.brand;
const everPublished = Boolean(payload.webflow_state && payload.webflow_state.ever_published);

const baseUrl = String((payload.brand && payload.brand.erpnext_base_url) || 'https://app.illumenate.lighting').replace(/\/$/, '');
// Spaces and other characters Webflow cannot fetch are percent-encoded; existing %XX escapes,
// slashes and brackets are kept, so an already encoded URL is not encoded twice.
const encodeUrl = url => String(url).replace(/[^A-Za-z0-9\-._~:/?#\[\]@!$&'()*+,;=%]/g, ch => encodeURIComponent(ch));
const fullUrl = path => (!path ? null : encodeUrl(/^https?:\/\//.test(path) ? path : baseUrl + (path.startsWith('/') ? '' : '/') + path));
const json = list => (Array.isArray(list) && list.length ? JSON.stringify(list) : '');

// --- Status (plan 4.19 Q1): Published/Discontinued are published; a Webflow Draft is staged
// only, or published hidden once it was ever published; Archived is archived. Unknown values
// fail closed (never public).
let isDraft = false;
let isArchived = false;
let hiddenFromPublic = true;
// The template's Product Status can override the product's Webflow Status (owner, 2026-11-08,
// plan 4.3): ERPNext sends the status to use as webflow_state.effective_status.
const effectiveStatus = payload.webflow_state && payload.webflow_state.effective_status;
switch ((effectiveStatus != null ? effectiveStatus : product.custom_webflow_status) || '') {
  case 'Published':
  case 'Discontinued':
    hiddenFromPublic = false;
    break;
  case 'Archived':
    isArchived = true;
    break;
  default: // Webflow Draft, empty or unknown
    isDraft = !everPublished;
}

// --- Kit components: grouped by component type in template order, the same output as the
// spec sheet's Get Product Info: [{component_type, component_description: JSON of
// [{hero_image}, {code, label}, ...]}].
function kitGroups(rows) {
  const groups = new Map();
  for (const row of rows || []) {
    if (!row.component_type) continue;
    if (!groups.has(row.component_type)) groups.set(row.component_type, {image: null, items: []});
    const group = groups.get(row.component_type);
    if (!group.image && row.component_image) group.image = fullUrl(row.component_image);
    group.items.push({code: row.component_item || '', label: String(row.component_description || '').trim()});
  }
  return Array.from(groups, ([type, group]) => ({
    component_type: type,
    component_description: JSON.stringify([...(group.image ? [{hero_image: group.image}] : []), ...group.items], null, 1),
  }));
}

let galleryFormatted = (product.gallery_images || [])
  .map(img => fullUrl(img.image_url || img.file_url || img.image))
  .filter(Boolean)
  .map(url => ({url}));

const generatedSlug = product.product_slug || String(product.name || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');

// Pacific date at noon UTC.
const pt = new Date(new Date().toLocaleString('en-US', {timeZone: 'America/Los_Angeles'}));
const finalSyncDate = `${pt.getFullYear()}-${String(pt.getMonth() + 1).padStart(2, '0')}-${String(pt.getDate()).padStart(2, '0')}T12:00:00.000Z`;

const fieldData = {
  // 1, 2, 12, 14
  name: (tpl && tpl.display_name) || product.product_name || product.name,
  slug: generatedSlug,
  'last-synced': finalSyncDate,
  'erp-sync-id': product.name,
  // 3
  'hidden-from-public': hiddenFromPublic,
  // 7 to 10 (product)
  'short-description': product.short_description || '',
  'featured-image': fullUrl(product.featured_image),
  gallery: galleryFormatted.length ? galleryFormatted : null,
  'family-image': fullUrl(product.series_family_image),
  // 11, 26 (template)
  'series-display-name': tpl ? (tpl.series_name || '') : (product.series_display_name || ''),
  subheading: tpl ? (tpl.sublabel || '') : (product.sublabel || ''),
  // The product's Dimensions Image; the template's is for the spec sheet only (owner, 2026-11-06).
  dimensions: fullUrl(product.dimensions_image_light || product.dimensions_image),
  // 13, 15, 17, 19, 20, 28 (product)
  'is-configurable-3': product.is_configurable === 1 || product.is_configurable === true,
  'attribute-links-json': json(product.attribute_links),
  'compatible-products-json': json(product.compatible_products),
  // In display order, so the Spec Sheet (the stable spec_sheet_public_url link, order 1) is first.
  'documents-json': json((product.documents || []).slice().sort((a, b) => (a.display_order || 0) - (b.display_order || 0))),
  'features-json': product.features_json || json(product.features),
  'product-badge': product.product_badge || '',
  // Web Badge (owner, 2026-11-05): the product's webflow_badge into the new web-badge field.
  'web-badge': product.webflow_badge || '',
  // 16, 18, 22, 23 (template)
  'certifications-json': json(((tpl && tpl.certifications) || []).map(row => ({...row, badge_image: fullUrl(row.badge_image)}))),
  'configurator-options-json': json(tpl ? tpl.configurator : []),
  'kit-components-json': json(kitGroups(tpl ? tpl.kit_components : [])),
  'specifications-json': json(tpl ? tpl.specifications : []),
};
// 25: template Price per Foot (MSRP), else Base Price (MSRP)
if (tpl && tpl.price_per_foot_msrp != null) fieldData['price-per-foot-msrp'] = tpl.price_per_foot_msrp;
// 6: category reference (this brand's category item)
if (product.category_webflow_item_id) fieldData.category = product.category_webflow_item_id;

return {
  json: {
    originalProduct: {
      webflow_item_id: product.webflow_item_id || null,
      product_slug: generatedSlug,
      brand,
      job: data.job || '',
      token: data.token || '',
      revision_hash: data.revision_hash || '',
      payload_hash: data.payload_hash || '',
    },
    webflow_collection_id: data.webflow_collection_id,
    webflowData: {isArchived, isDraft, fieldData},
  },
};

